        R := 0.7;
        dAngle := (Arctan(2) + Arcsin(2/3)) / 2;
        dAngle2 := (Arctan(2) - Arcsin(2/3)) / 2;
        Rsin := R * sin(dAngle);
        Rcos := R * cos(dAngle);
        R2sin := R * sin(dAngle2);
        R2cos := R * cos(dAngle2);
        sAngle := PI * 2 / 5;

        for i := 0 to 4 do begin
            x[i] := Rcos * sin(sAngle * (i - 0.5));
            y[i] := Rcos * cos(sAngle * (i - 0.5));
            z[i] := Rsin;
        end;
        for i := 5 to 9 do begin
            x[i] := R2cos * sin(sAngle * (i - 0.5));
            y[i] := R2cos * cos(sAngle * (i - 0.5));
            z[i] := R2sin;
        end;

        mAngle := ArcTan(0.5);
        As := sin(mAngle);
        Ac := cos(mAngle);
        for i := 1 to 5 do begin
            mx[i] := sin(sAngle * (i - 1)) * Ac;
            my[i] := cos(sAngle * (i - 1)) * Ac;
        end;

        D := (Rsin + R2sin) / 2;
        D1 := (3 * Rsin + 1 * R2sin) / 4;
        D2 := (2 * Rsin + 2 * R2sin) / 4;
